const norm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\([^)]*\)/g,' ').replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' ');
const aliases=[['aji lamu pantomime','aji lhamu','aji lamu'],['pangong tso','pangong lake'],['churches and convents of old goa','churches and convents of goa'],['nati','nati dance'],['fugdi','fugdi dance'],['rouff','rouf','rouf dance'],['chhau dance of purulia','chhau of purulia'],['oggu katha','oggukatha'],['channapatna wooden toys','channapatna toys and dolls'],['kondapalli toys','kondapalli bommallu'],['sohrai painting','sohrai khovar painting'],['chamba rumal embroidery','chamba rumal'],['phulkari embroidery','phulkari'],['sao joao festival','sao joao'],['dohneiiong','doh sniang nei iong'],['nati','nati dance']];
const canon=s=>{const n=norm(s);for(const g of aliases)if(g.some(x=>norm(x)===n))return norm(g[0]);return n;};
const same=(a,b)=>canon(a)===canon(b);
const field=e=>e.field;
ADDITIONS.forEach(e=>{const c=window.CONTENT&&window.CONTENT[e.stateId];if(!c)return;const it=e.item;
  if(e.category==='stateAnimal'){if(!c.animal)c.animal=it;return;}
  const k=field(e);if(!Array.isArray(c[k]))c[k]=[];if(!c[k].some(x=>same(x.en,it.en)))c[k].push(it);
});
window.BME_M102_VERIFIED_ADDITIONS=ADDITIONS;
